<script setup>
import AccountSelect from '../components/AccountSelect.vue';
import {ref,computed,watch,onUnmounted} from 'vue';
import MasterEvidence from '../components/MasterEvidence.vue';
import XmlSourceFields from '../components/XmlSourceFields.vue';
import ThirdPartyPanel from '../components/ThirdPartyPanel.vue';
import BaseModal from '../components/BaseModal.vue';import LookupAssist from '../components/LookupAssist.vue';import RegistrationProfile from '../components/RegistrationProfile.vue';import DateInput from '../components/DateInput.vue';
import {state,company,api,scope,useResource,notify,changed,ask} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';import {normalized,periodDate,amount} from '../lib/format';
const thirdParty=ref(null),evidence=ref(null);
watch(()=>[state.companyId,state.period,state.module],()=>{thirdParty.value=null;evidence.value=null;},{flush:'sync'});
const props=defineProps({area:{type:String,default:'fiscal'}});
const allKinds={participant:'Clientes, fornecedores e transportadores',establishment:'Estabelecimentos',product:'Produtos',service:'Serviços',history:'Históricos',accounting_model:'Modelos de contabilização'};
const kinds=Object.fromEntries(Object.entries(allKinds).filter(([k])=>props.area==='accounting'?['history','accounting_model'].includes(k):!['history','accounting_model'].includes(k)));
const routine=props.area==='accounting'?'accounting.histories':'fiscal.masters';
const kind=ref(props.area==='accounting'?'history':'participant'),query=ref(''),page=ref(1),sort=ref('code'),show=ref(false),editing=ref(null),form=ref({}),error=ref(''),busy=ref(false),context=ref(null);let baseline='';
const {data,error:loadError,reload}=useResource(async()=>{if(!state.companyId)return {items:[],accounts:[],centers:[]};const [items,accounts,centers]=await Promise.all([api(scope(`/masters/${kind.value}`)),allowedApi('accounting.accounts',scope('/accounts')),allowedApi('accounting.cost_centers',scope('/cost-centers'))]);return {items,accounts,centers};},{items:[],accounts:[],centers:[]});
watch(kind,()=>{page.value=1;query.value='';reload();});watch([query,sort],()=>page.value=1);
const filtered=computed(()=>data.value.items.filter(r=>normalized(`${r.code} ${r.name} ${r.tax_id} ${r.data?.ncm||''} ${r.data?.cest||''} ${r.data?.barcode||''} ${r.data?.import_identity?.code||''}`).includes(normalized(query.value))).sort((a,b)=>String(a[sort.value]).localeCompare(String(b[sort.value]),'pt-BR',{numeric:true})));const visible=computed(()=>filtered.value.slice((page.value-1)*25,page.value*25));const registry=computed(()=>['participant','establishment'].includes(kind.value));
function open(row=null){editing.value=row;context.value={id:state.companyId,name:company.value.name};form.value={code:'',name:'',tax_id:'',active:true,...JSON.parse(JSON.stringify(row||{})),...JSON.parse(JSON.stringify(row?.data||{}))};form.value.profile??={ie_status:'unknown',state_registrations:[],secondary_cnaes:[]};form.value.roles??=['customer','supplier'];form.value.valid_from??=periodDate(state.period);form.value.status??='draft';form.value.direction??='both';form.value.price??='';baseline=JSON.stringify(form.value);error.value='';show.value=true;state.editor={name:'Cadastro auxiliar',companyId:state.companyId};}
function addPrincipalIe(){const number=(form.value.ie||'').trim(),state=(form.value.state||'').toUpperCase();if(!number||!state)return;const exempt=number.toUpperCase()==='ISENTO';form.value.profile.state_registrations??=[];if(form.value.profile.state_registrations.some(r=>r.state===state&&r.number===(exempt?'':number)))return;form.value.profile.state_registrations.push({state,number:exempt?'':number,status:exempt?'exempt':'',active:null,source:'IE principal do cadastro',updated_at:''});}
async function close(){if(busy.value)return;if(baseline!==JSON.stringify(form.value)&&!await ask({title:'Descartar edição?',message:'As alterações cadastrais ainda não foram salvas.',confirmLabel:'Descartar'}))return;show.value=false;state.editor=null;}
async function save(){busy.value=true;error.value='';try{const {code,name,tax_id,active,version,...details}=form.value;delete details.data;if(['product','service'].includes(kind.value)){if(String(details.price??'').trim())details.price=amount(details.price);else delete details.price;}await api(scope(`/masters/${kind.value}${editing.value?`/${editing.value.id}`:''}`,context.value.id),{method:editing.value?'PUT':'POST',body:{code,name,tax_id,active,version,data:details}});show.value=false;state.editor=null;changed();notify('Cadastro salvo.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
onUnmounted(()=>{if(show.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">CADASTROS INTEGRADOS</div><h1>Cadastros auxiliares</h1><p>Dados reutilizáveis na empresa ativa, com revisão e histórico.</p></div><button class="button primary" v-allow="[routine,'create']" @click="open()">Novo cadastro</button></header><div v-if="loadError" class="message error">{{loadError}}</div><section class="panel"><div class="table-toolbar"><select v-model="kind" aria-label="Tipo de cadastro"><option v-for="(name,key) in kinds" :value="key" :key="key">{{name}}</option></select><input v-model="query" placeholder="Código, nome, CPF/CNPJ, NCM ou GTIN" aria-label="Pesquisar cadastros"/><select v-model="sort" aria-label="Ordenação dos cadastros"><option value="code">Ordenar por código</option><option value="name">Ordenar por nome</option></select></div><div class="table-scroll"><table><thead><tr><th>Código</th><th>Nome</th><th v-if="registry">CPF/CNPJ</th><template v-if="['product','service'].includes(kind)"><th>NCM / CEST</th><th>Unidade / código de origem</th></template><th>Situação</th><th>Ação</th></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td>{{r.code}}</td><td>{{r.name}}</td><td v-if="registry">{{r.tax_id}}</td><template v-if="['product','service'].includes(kind)"><td>{{r.data.ncm||'Não informado'}}<small class="cell-secondary">{{r.data.cest||'CEST não informado'}}</small></td><td>{{r.data.unit||'Não informada'}}<small class="cell-secondary">{{r.data.import_identity?.code||r.data.barcode||'—'}}</small></td></template><td>{{r.active?'Ativo':'Inativo'}}<span v-if="kind==='accounting_model'"> · {{r.data.status==='validated'?'Revisado':'Rascunho'}}</span></td><td><button v-if="['participant','establishment','product','service'].includes(kind)" type="button" class="button small" @click="evidence=r">Consultar dados e XMLs</button><button v-if="registry&&can('fiscal.masters')" class="button small" @click="thirdParty=r">Identidade e histórico</button><button class="button small" v-allow="[routine,'edit']" @click="open(r)">Editar</button></td></tr></tbody></table></div><footer class="table-footer"><span>{{filtered.length}} registros · página {{page}}</span><div class="actions"><button class="button small" @click="page--" :disabled="page===1">Anterior</button><button class="button small" @click="page++" :disabled="page*25>=filtered.length">Próxima</button></div></footer></section>
<BaseModal v-if="evidence" :title="`${evidence.code} · ${evidence.name}`" :subtitle="`Cadastro da empresa ${company.name}`" wide @close="evidence=null"><XmlSourceFields title="Dados atuais do cadastro" :value="{code:evidence.code,name:evidence.name,tax_id:evidence.tax_id,active:evidence.active,...evidence.data}"/><MasterEvidence :master="evidence" :company-id="state.companyId"/><template #footer><button type="button" class="button" @click="evidence=null">Fechar</button></template></BaseModal>
<ThirdPartyPanel v-if="thirdParty" :master="thirdParty" @close="thirdParty=null"/>
<BaseModal v-if="show" :title="`${editing?'Editar':'Novo'} cadastro`" :subtitle="`${kinds[kind]} · ${context.name}`" wide @close="close"><p v-if="error" class="message error" role="alert">{{error}}</p><form id="master-form" @submit.prevent="save"><div class="form-grid three"><label>Código *<input v-model="form.code" required autofocus/></label><label class="span-2">Nome / razão social *<input v-model="form.name" required/></label><label v-if="registry">CPF/CNPJ<input v-model="form.tax_id" :readonly="!!editing"/></label><label>Situação<select v-model="form.active"><option :value="true">Ativo</option><option :value="false">Inativo</option></select></label></div>
<template v-if="registry"><LookupAssist :target="form"/><div class="form-grid three"><label>Nome fantasia<input v-model="form.trade_name"/></label><label>E-mail<input v-model="form.email" type="email"/></label><label>Telefone<input v-model="form.phone"/></label><label>CEP<input v-model="form.postal_code"/></label><label class="span-2">Logradouro<input v-model="form.address"/></label><label>Número<input v-model="form.number"/></label><label>Bairro<input v-model="form.district"/></label><label>Município<input v-model="form.city"/></label><label>UF<input v-model="form.state" maxlength="2"/></label><label>Código IBGE<input v-model="form.ibge"/></label><label>CNAE principal<input v-model="form.cnae"/></label><label>IE principal<input v-model="form.ie"/></label><label>Inscrição municipal<input v-model="form.im"/></label><label>Código na Prosoft<input v-model="form.prosoft_code"/></label><label>País<input v-model="form.country"/></label><label>Código do país<input v-model="form.country_code"/></label><label>CRT declarado<input v-model="form.crt"/></label><label>Indicador de IE declarado<input v-model="form.ie_indicator"/></label><label>Inscrição SUFRAMA<input v-model="form.suframa"/></label><label>IE de substituto<input v-model="form.ie_substitute"/></label><label>Identificação estrangeira<input v-model="form.foreign_id"/></label></div><LookupAssist :target="form" kind="cep"/><div v-if="kind==='participant'" class="actions"><label v-for="(label,key) in {customer:'Cliente',supplier:'Fornecedor',carrier:'Transportador',other:'Outro'}" :key="key" class="inline-choice"><input type="checkbox" v-model="form.roles" :value="key"/>{{label}}</label></div><p class="message subtle">Inscrições abaixo pertencem ao CPF/CNPJ completo {{form.tax_id||'deste cadastro'}}. A mesma raiz do CNPJ não une inscrições de filiais.</p><button v-if="form.ie&&form.state" type="button" class="button small" @click="addPrincipalIe">Adicionar IE principal à grade</button><RegistrationProfile :model="form.profile"/></template>
<div v-if="['product','service'].includes(kind)" class="form-grid three"><label>Unidade comercial<input v-model="form.unit"/></label><label>Unidade tributável<input v-model="form.tax_unit"/></label><label>Preço de referência<input v-model="form.price" inputmode="decimal" placeholder="Não informado"/></label><label>NCM<input v-model="form.ncm" maxlength="8"/></label><label>CEST<input v-model="form.cest" maxlength="7"/></label><label>EXTIPI<input v-model="form.extipi"/></label><label>Origem da mercadoria<input v-model="form.origin"/></label><label>CFOP de referência<input v-model="form.cfop" maxlength="4"/></label><label>Código do serviço<input v-model="form.service_code"/></label><label>GTIN comercial<input v-model="form.barcode"/></label><label>GTIN tributável<input v-model="form.tax_barcode"/></label><label>Código do fabricante<input v-model="form.manufacturer_code"/></label><label>Benefício fiscal de referência<input v-model="form.benefit_code"/></label><label>Código ANP<input v-model="form.anp_code"/></label><label>CST de referência<input v-model="form.cst"/></label><label>cClassTrib de referência<input v-model="form.cclass_trib"/></label></div>
<p v-if="['product','service'].includes(kind)" class="message subtle">Preços, CFOP e classificações de referência exigem revisão. Valores, bases, alíquotas e impostos de cada nota permanecem disponíveis em Consultar dados e XMLs e não são aplicados automaticamente.</p><label v-if="kind==='history'">Texto do histórico *<textarea v-model="form.text" required rows="4"/></label>
<template v-if="kind==='accounting_model'"><div class="form-grid"><label>Conta a debitar *<AccountSelect v-model="form.debit_account_id" required :accounts="data.accounts.filter(a=>a.active&&a.analytical)" empty-label="Selecione"/></label><label>Conta a creditar *<AccountSelect v-model="form.credit_account_id" required :accounts="data.accounts.filter(a=>a.active&&a.analytical)" empty-label="Selecione"/></label><label>Centro de custo<select v-model.number="form.cost_center_id"><option :value="null">Sem centro</option><option v-for="c in data.centers" :value="c.id" :key="c.id">{{c.code}} · {{c.name}}</option></select></label><label>Operação<select v-model="form.direction"><option value="both">Entradas e saídas</option><option value="incoming">Entrada</option><option value="outgoing">Saída</option></select></label><label>Início da vigência *<DateInput v-model="form.valid_from" required/></label><label>Fim da vigência<DateInput v-model="form.valid_to"/></label><label>Status<select v-model="form.status"><option value="draft">Rascunho</option><option value="validated">Revisado</option></select></label><label>Responsável pela revisão<input v-model="form.responsible" :required="form.status==='validated'"/></label><label class="span-2">Fonte / orientação contábil<input v-model="form.source" :required="form.status==='validated'"/></label><label class="span-2">Histórico<input v-model="form.history" :required="form.status==='validated'"/></label></div><p class="message subtle">O modelo contabiliza o total documental. A aplicação exige escolha explícita durante a escrituração.</p></template>
</form><template #footer><button class="button" @click="close" :disabled="busy">Cancelar</button><button class="button primary" form="master-form" :disabled="busy">Salvar cadastro</button></template></BaseModal></div></template>
